/* ── Draft Status Bar (inside modal) ── */
.lr-draft-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  margin: 0 0 8px;
  border-radius: 6px;
  background: #f0f7ff;
  border: 1px solid #c8ddf5;
  font-size: 12px;
  color: #3d6ba8;
}
.lr-draft-bar--error {
  background: #fff4e5;
  border-color: #f0c36d;
  color: #a67c00;
}
.lr-draft-bar-icon {
  font-size: 16px;
  flex-shrink: 0;
}
.lr-draft-bar-text {
  flex: 1;
  min-width: 0;
}
.lr-draft-bar-clear {
  all: unset;
  cursor: pointer;
  font-size: 11px;
  color: #c0392b;
  padding: 2px 8px;
  border-radius: 4px;
  white-space: nowrap;
}
.lr-draft-bar-clear:hover {
  background: rgba(192, 57, 43, 0.08);
}

/* ── Draft List Button (header) ── */
.lr-draft-list-btn {
  position: relative;
}
.lr-draft-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  border-radius: 9px;
  background: #FB8C00;
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  padding: 0 5px;
  margin-left: 4px;
  line-height: 1;
}

/* ── Draft Panel Modal ── */
.lr-draft-panel {
  max-height: 80vh;
  display: flex;
  flex-direction: column;
}
.lr-draft-panel-body {
  flex: 1;
  overflow-y: auto;
  padding: 0 16px 16px;
}

/* Empty state */
.lr-draft-empty {
  text-align: center;
  padding: 32px 16px;
}
.lr-draft-empty-icon {
  font-size: 48px;
  color: #bbb;
  margin-bottom: 12px;
}
.lr-draft-empty-text {
  font-size: 15px;
  font-weight: 600;
  color: #555;
  margin: 0 0 6px;
}
.lr-draft-empty-hint {
  font-size: 13px;
  color: #888;
  margin: 0;
  line-height: 1.5;
}

/* Draft items */
.lr-draft-items {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-top: 8px;
}
.lr-draft-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 8px;
  background: #fafafa;
  border: 1px solid #eee;
  transition: background 0.15s;
}
.lr-draft-item:hover {
  background: #f0f7ff;
  border-color: #c8ddf5;
}
.lr-draft-item-info {
  flex: 1;
  min-width: 0;
  cursor: default;
}
.lr-draft-item-student {
  font-size: 14px;
  font-weight: 600;
  color: #333;
